  "vidcfg.minimaxH3ResNote": "2K (default) or 768P output — 768P bills at the cheaper per-second rate. “adaptive” matches the wired input; pure text-to-video renders 16:9 unless a concrete ratio is picked. Audio is always generated — lip-synced to reference audio when connected.",
