  "vidcfg.switchxHelpSelect": "Provide one keyframe mask image (e.g. wire a Generate Mask node into the Mask input); the AI propagates it across the video.",
  "vidcfg.switchxHelpCustom": "Provide a full per-frame alpha matte video for frame-accurate control.",
