  "vidcfg.sameSeedSimilar": "Same seed produces similar results. Leave empty for random.",
  "vidcfg.veo31Audio": "VEO 3.1 creates AI audio from the prompt. Disable for silent video, then use Add Audio node.",
  "vidcfg.veoAutoTranslateNote": "Prompts are auto-translated to English before VEO sees them (default on). Disable to keep prompts verbatim — useful for non-English prompts or when exact wording matters (e.g. the perfect-loop seal phrase).",
  "vidcfg.veoAutoTranslateNoteShort": "Prompts are auto-translated to English before VEO sees them (default on). Disable to keep prompts verbatim.",
  "vidcfg.worksBestSameFrames": "Works best when start and end frames are pinned to the same image. Without an end frame, the algorithm picks the best loop point it can find but the result may not be seamless.",
