  "audiocfg.descTalkingHeadFaceEnh": "Connect a talking-head video and audio track. Includes built-in face enhancement.",
  "audiocfg.descPortraitTalkingHead": "Connect a portrait image and an audio track (speech/voiceover) to generate a talking head video.",
  "audiocfg.descSingingDiffusion": "Connect a video and audio track. Best for singing — uses diffusion for high-quality lip sync.",
  "audiocfg.descFastCheapLipSync": "Connect a video or image and audio track. Fast and cheap lip sync.",
  "audiocfg.descPortraitNaturalMotion": "Connect a portrait image and audio to generate a talking head with natural motion.",
  "audiocfg.descAvatarInference": "Connect a video and an audio track to replace/dub the speech with high-accuracy avatar-inference lip sync. Billed per second of output.",
  "audiocfg.descStudioGrade": "Connect a video (.mp4) and an audio track (.wav) for studio-grade lip sync. Billed per second of output.",
  "audiocfg.descSyncSo": "Connect a video and an audio track to dub the footage with sync.so v3 (fal.ai). Billed per second of output.",
  "audiocfg.descVolcengine": "Connect a video and an audio track to dub the footage (Volcengine). Output length follows the audio. Billed per second; ~2 credits/second.",
  "audiocfg.descVoiceExtractor": "Removes background noise and extracts clean voice from any audio input. Connect an audio source (Upload Audio, Text to Speech, etc.) to the input.",
  "audiocfg.hintSpeakerBoostDesc": "Amplifies the source's delivery. Keep at 0 unless you want more drama — higher values add latency and can reduce stability.",
  "audiocfg.hintSimilarityBoostDesc": "Amplifies similarity to the target voice (uses more compute, slight latency). On by default.",
  "audiocfg.hintSeedReproducible": "Fix for reproducible output (same seed + same input + same settings). Leave blank for random.",
  "audiocfg.hintDubCloneDesc": "By default the dub CLONES the original speaker — they speak the target language with their own voice and accent. Check this to use a similar native-sounding voice instead.",
  "audiocfg.hintDubTranslate": "Translates speech to the target language. Connect an audio source to the input.",
  "audiocfg.descVoiceDesign": "Generates a new voice from a natural language description and creates an audio preview with the specified text.",
  "audiocfg.descForcedAlign": "Aligns audio with a transcript to produce word-level timestamps. Connect an audio source to the input.",
  "audiocfg.descRecast1": "Speakers are detected automatically. Voice 1 recasts the first speaker to talk, voice 2 the",
