  "tut.ccvInTitle": "The reference frame",
  "tut.ccvInSub": "One image. This is the scene.",
  "tut.ccvRefPromptEyebrow": "Reference prompt",
  "tut.ccvBriefEyebrow": "The coverage brief · edit this to change the plan",
  "tut.ccvBriefRule1": "Real coverage order: wide, two mediums, two close-ups, over-the-shoulder, reverse, insert, dynamic angle, profile.",
  "tut.ccvBriefRule2": "One camera angle per line. Never stack two angle terms.",
  "tut.ccvBriefRule3": "Camera position, not movement. Motion is added later.",
  "tut.ccvBriefRule4": "Screen direction stays consistent, so the cuts do not jump.",
  "tut.ccvBriefRule5": "Leave breathing room. Every frame must work as a start frame for animation.",
